#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.."&&pwd -P)";WORKSPACE="$(realpath -e -- "${WORKSPACE_ROOT:-/guisongxia01/pangchao/wangyihan}")";PRIMARY="$(realpath -e -- "${PRIMARY_REPO:-$WORKSPACE/Chang-Agent}")";OUTPUT_ROOT="$(realpath -e -- "$PRIMARY/outputs")"
RUN_DIR="$(realpath -m -- "${RUN_DIR:-$OUTPUT_ROOT/CA_0801(9)-qwen3vl-v121-baseline-sft-v1}")";DATASET_DIR="$(realpath -e -- "${DATASET_DIR:?DATASET_DIR required}")";NODE="${NODE:?NODE required}";WORKER="$ROOT/tools/run_qwen3vl_v121_baseline_sft.slurm";COMMIT="$(git -C "$ROOT" rev-parse HEAD)";JOB_NAME="${JOB_NAME:-CA0801V121SFT}"
[[ "$RUN_DIR" == "$OUTPUT_ROOT/"* && ! -e "$RUN_DIR" ]]||{ echo "unsafe/existing output" >&2;exit 2; };[[ -f "$DATASET_DIR/.data_complete" ]]||exit 2;[[ -z "$(git -C "$ROOT" status --porcelain --untracked-files=all)" ]]||exit 2
scontrol ping|grep -q UP||exit 3;ACTIVE="$(squeue -h -u guisongxia --name="$JOB_NAME" -o '%i %T')";[[ -z "$ACTIVE" ]]||{ echo "duplicate $ACTIVE" >&2;exit 2; };INFO="$(scontrol show node "$NODE")";grep -Eq 'State=[^ ]*(DOWN|DRAIN|FAIL|MAINT)'<<<"$INFO"&&exit 2
mkdir "$RUN_DIR";mkdir "$RUN_DIR/logs";JOB="$(sbatch --parsable --job-name="$JOB_NAME" --partition=gre --nodelist="$NODE" --gres=gpu:2 --cpus-per-task=8 --mem=96G --time=02:00:00 --output="$RUN_DIR/logs/slurm-%j.out" --error="$RUN_DIR/logs/slurm-%j.err" --export="ALL,REPO_ROOT=$ROOT,WORKSPACE_ROOT=$WORKSPACE,DATASET_DIR=$DATASET_DIR,EXPECTED_COMMIT=$COMMIT,LEARNING_RATE=${LEARNING_RATE:-3.0e-5},NUM_TRAIN_EPOCHS=${NUM_TRAIN_EPOCHS:-2.0}" "$WORKER" "$RUN_DIR")";JOB="${JOB%%;*}"
printf 'job_id=%s\nnode=%s\nresources=gpu:2,cpu:8,mem:96G,time=02:00:00\ncode_commit=%s\ndataset=%s\noutput=%s\n' "$JOB" "$NODE" "$COMMIT" "$DATASET_DIR" "$RUN_DIR" >"$RUN_DIR/submission.txt";printf 'job=%s\noutput=%s\n' "$JOB" "$RUN_DIR"
